  detail().click();cy.get('[data-testid="details-panel"]').should('contain.text','DEMO-123');
  cy.intercept('POST','/__rpc/board.read',{body:{...registryBoard,issues:registryBoard.issues.filter(issue=>issue.key!=='DEMO-123')}});
  button('Refresh').click();cy.contains('Nothing selected').should('be.visible');
  cy.get('[data-cy-root]').screenshot('registry-empty-selection');
